@spec tuning_spec  src=tests/specs/tuning_spec.lua  loc=1127  cases=70
@exercises tuning (tuning)
@surface   tuning.derive, tuning.stepToParts, tuning.genRank2, tuning.stepToMidi, tuning.midiToStep, tuning.scalaPitch, tuning.unrooted, tuning.removeStep, tuning.sortSteps, tuning.midiName, tuning.stepWindow, tuning.parseScalaFile, tuning.parseScalaPitches, tuning.scalaToTemper, tuning.genEqual, tuning.edoDegrees, tuning.degreesToSpec, tuning.genHarmonics, tuning.genSubharmonics, tuning.parseChord, tuning.genChord, tuning.genCPS, tuning.genDiamond, tuning.genTenney, tuning.isTarget, tuning.nextMosSize, tuning.mosInfo, tuning.coords, tuning.ratio, tuning.height, tuning.moves, tuning.stepClass, tuning.noteStep, tuning.seatWindow, tuning.seat, tuning.shortlist

# Intent
  Pins tuning.lua's pure display + derivation layer: the Option-B nameless
  step labels, the derived octaveStep / cellWidth fields, and the coordinate
  conversions between MIDI and step-octave. Realisation invariants (I1-I5)
  live in tm_tuning_spec; projection wiring in view_context_spec.

# Helpers
  @fn nameless(cents)  @ 10-12
  @fn holds(gen, token)  @ 15-18
      -- Token membership in a generated scale, for a point set too large to state entire.
  @fn stepText(temper, step, octave)  @ 22-25
      -- The two label parts joined, so a case that is about the whole label can
      -- assert it as one string.
  @fn rooted(root)  @ 28-34
      -- A 12EDO scale with the root fields the case is about; everything else default.
  @fn authored(root)  @ 38-43
      -- The same 12EDO in the shape a step edit sees: pitch tokens, names densified
      -- to '' as cloneForEdit leaves them, so sortSteps and removeStep can drive it.
  @fn meantone12()  @ 47-51
      -- Quarter-comma meantone's twelve-note MOS (Eb..G#, C at the unison): an
      -- unequal scale, so a step's two neighbours sit at different distances.
  @fn noteAt(pitch, detune, intentCents)  @ 54-56
      -- A note as the step readers take one: where it sounds, and where it was written.
  @fn nearly(got, want, why)  @ 60-62
      -- A candidate's cents and strain are irrational in general, so a case that names
      -- one names it to four places.
  @fn half12()  @ 66-70
      -- 12EDO written as six equal steps of a half-octave period: a step index that
      -- recurs inside the octave, on a step a tritone from the one it repeats.
  @fn bp13()  @ 74-79
      -- Bohlen-Pierce's thirteen equal divisions of 3/1, rooted so step 1 is C4: a
      -- period that is not the octave, so the step an octave up is a different step.
  @fn soundsA415(temper, step, why)  @ 87-91
      -- What the rooted step sounds, as (midi, detune); the deletions and sorts below
      -- all claim to leave it alone.

# Cases
  @case 'preset EDOs derive width 3 and a past-the-end octaveStep'  [pure]  @ 95-105
  @case 'named step renders name + octave'  [pure]  @ 109-114
  @case 'a negative octave renders as its magnitude and reports the sign'  [pure]  @ 118-127
  @case 'the octaveStep bump owns the sign: a step that crosses zero is not negative'  [pure]  @ 131-138
  @case 'nameless step falls back to degree-octave with a dash'  [pure]  @ 142-150
  @case 'nameless scale past 9 steps widens the cell for 2-digit degrees'  [pure]  @ 154-161
  @case 'sub-octave period widens the octave field for 2-digit octaves'  [pure]  @ 165-174
  @case 'a root numbering the octaves near zero narrows the field'  [pure]  @ 178-198
  @case 'a root numbering the range low makes the bottom end the wider'  [pure]  @ 202-214
  @case 'derive recomputes width when names are dropped'  [pure]  @ 218-226
  @case 'partially named scale: named steps keep their label, blanks fall back'  [pure]  @ 230-237
  @case 'scalaPitch parses ratios, cents, bare integers and n\\m steps'  [pure]  @ 241-255
  @case 'derive compiles pitches → cents and periodPitch → period'  [pure]  @ 259-267
  @case 'derive reduces an authored root to rootCents + octaveBase'  [pure]  @ 271-281
  @case 'a preset states no root and derives the default (0,0) = (1,-1)'  [pure]  @ 285-294
  @case 'unrooted is the library form: the four dropped, the stamps back at the default'  [pure]  @ 298-309
  @case 'a deleted step takes the root\'s index down with it'  [pure]  @ 313-323
  @case 'deleting the rooted step restates the root on the unison'  [pure]  @ 327-344
  @case 'a step sorted below the root carries the root\'s index'  [pure]  @ 348-357
  @case 'retuning the rooted step moves the scale, not the root'  [pure]  @ 361-374
  @case 'a temper stating no root comes through both edits unstamped'  [pure]  @ 378-389
  @case 'midiName spells a pitch in the untempered twelve names'  [pure]  @ 393-399
  @case 'the default root reduces the conversions to MIDI-relative arithmetic'  [pure]  @ 403-418
  @case 'stepWindow halves the distance to each neighbour, wrapping at both ends'  [pure]  @ 422-435
  @case 'stepWindow under an unequal scale reports two different halves'  [pure]  @ 439-451
  @case 'a flattened root moves every pitch by its offset and renames nothing'  [pure]  @ 455-477
  @case 'an octave-shifted root renames every octave and moves no pitch'  [pure]  @ 481-497
  @case 'the conversions invert each other at every root'  [pure]  @ 501-514
  @case 'EDO presets carry n\\m source tokens that derive back to their cents'  [pure]  @ 518-525
  @case 'parseScalaFile strips comments, description and count; returns pitch tokens'  [pure]  @ 529-537
  @case 'parseScalaPitches keeps every non-comment, non-blank line'  [pure]  @ 541-546
  @case 'scalaToTemper prepends the unison, splits the period, flags periodAsStep'  [pure]  @ 550-561
  @case 'scalaToTemper sorts unordered pitches ascending; widest becomes the period'  [pure]  @ 565-574
  @case 'scalaToTemper rejects an unparseable token'  [pure]  @ 578-583
  @case 'genEqual: full EDO and a diatonic subset, base implicit, period last'  [pure]  @ 587-599
  @case 'edoDegrees: relative cumulates, absolute sorts; non-octave equave suffixes'  [pure]  @ 603-611
  @case 'degreesToSpec round-trips edoDegrees in both modes'  [pure]  @ 615-619
  @case 'genHarmonics / genSubharmonics: rooted on the low harmonic, top is period'  [pure]  @ 623-632
  @case 'genChord: otonal vs inverted, last member is the period'  [pure]  @ 636-648
  @case 'parseChord rejects fewer than two notes or non-integers'  [pure]  @ 652-656
  @case 'genCPS: hexany rooted on the smallest product, 1/1 first, ascending'  [pure]  @ 660-666
  @case 'genDiamond: the 9-diamond entire, and the counts either side of it'  [pure]  @ 670-680
  @case 'genDiamond: the prime limit filters in place, and leaves a tritone hole'  [pure]  @ 684-695
  @case 'genTenney: the eleven points 3/2 and 5/4 compose to under 15/8'  [pure]  @ 699-707
  @case 'genTenney: the bound is what a chain spends, so a wider one buys spellings'  [pure]  @ 711-722
  @case 'genTenney: generators are intervals, so a ball may sit on a sublattice'  [pure]  @ 726-736
  @case 'genTenney: a point composition reaches that a walk within the bound cannot'  [pure]  @ 740-746
  @case 'genRank2: pure-fifth size 7 / up 5 is Pythagorean major, 1/1 first'  [pure]  @ 750-756
  @case 'genRank2: size 4 / up 2 matches the Scale Workshop worked example'  [pure]  @ 760-765
  @case 'genRank2: irrational (EDO-step) generator emits cents tokens'  [pure]  @ 769-774
  @case 'nextMosSize / mosInfo: pure-fifth ladder 2->3->5->7->12; 7 is 5L 2s'  [pure]  @ 778-790
  @case 'coords: the exponents of the odd primes, prime 2 divided out'  [pure]  @ 794-804
  @case 'coords: an unreduced token reads as the interval it states'  [pure]  @ 808-813
  @case 'ratio: coords spelled back as a token, reduced into the octave'  [pure]  @ 817-826
  @case 'coords: a token that is not a ratio carries none'  [pure]  @ 830-836
